package com.finflow.payment; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.*; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.time.*; @Component @EnableScheduling class OutboxPublisher{private final OutboxRepository r;private final KafkaTemplate<String,String> k;OutboxPublisher(OutboxRepository r,KafkaTemplate<String,String> k){this.r=r;this.k=k;}@Scheduled(fixedDelayString="${outbox.poll-ms:1000}")@Transactional void publish(){for(var e:r.findTop100ByStatusOrderByCreatedAt("PENDING")){try{k.send(e.eventType,e.aggregateId.toString(),e.payload).get();e.status="PUBLISHED";e.publishedAt=Instant.now();}catch(Exception x){e.attempts++;}}}}